use std::collections::HashMap;
fn main() {
    let mut counts: HashMap<String, u32> = HashMap::new();
    for word in ["read", "read"] {
        *counts.entry(String::from(word)).or_insert(0) += 1;
    }
    println!("{}", counts.len());
}

use std::fmt;
#[derive(Debug)]
struct InvalidMinutes;
impl fmt::Display for InvalidMinutes {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "minutes must be 1 through 60")
    }
}
impl std::error::Error for InvalidMinutes {}
fn main() {
    println!("{}", InvalidMinutes);
}

use std::sync::atomic::{AtomicUsize, Ordering};
fn main() {
    let count = AtomicUsize::new(0);
    count.store(7, Ordering::SeqCst);
    println!("{}", count.load(Ordering::SeqCst));
    count.store(2, Ordering::SeqCst);
    println!("{}", count.load(Ordering::SeqCst));
}
